// B4 -- mensagem de falha para o operador por email (X3: CallMeBot morto, bot cheio ha semanas -- substituido por email).
// O Error Trigger corre quando qualquer workflow com este como "error workflow"
// (ver settings.errorWorkflow em imovel-landing-wf.json) falha a execucao --
// inclui tanto a validacao G1 (campos em falta) como o bloqueio do Porteiro (S2)
// e falhas tecnicas (Gemini, download de fotos, etc). Nao inventa detalhe: usa
// a mensagem de erro real, que ja e descritiva (ver os throw new Error(...) nos
// nos de origem).
const evt = $json;
const errorMessage = evt.execution?.error?.message
  || evt.execution?.lastNodeExecuted?.error?.message
  || evt.error?.message
  || 'Erro desconhecido -- ver execucao no n8n.';
const workflowName = evt.workflow?.name || 'workflow desconhecido';
const executionUrl = evt.execution?.url || '';

let texto = 'Prisma: falha no pipeline "' + workflowName + '"\n' + errorMessage;
if (executionUrl) texto += '\n' + executionUrl;
const subject = 'PRISMA: falha no pipeline -- ' + workflowName;

return [{ json: { texto, subject } }];
